/* The wasm32 backend's case list: one C program per line of the
 * language, with what it must answer.
 *
 * Two proves read this file, because neither alone is enough:
 *
 *   externals/tcc/wasm32_prove.c   compiles every case and validates
 *       the module (sections tile, indices in range). It links libtcc
 *       and no engine, so it cannot check answers.
 *   jit/c/__tests__.c              compiles every case for the wasm32
 *       lane, loads it through the wasmmod loader and CALLS it, which
 *       is the only check that catches a module that loads and lies.
 *
 * Every case is `int f(int x)` and is called once per argument, in
 * order — cases with static or global state depend on that order.
 *
 * The expected values are gcc -m32's, on the same source: wasm32 is
 * ILP32 like i386, so the two agree except where the target ABI or C
 * itself differs, and those two cases say so where they sit.
 */

/* name, source, and one answer per WASM32_CASE_ARGS entry */
typedef struct wasm32_case {
    const char *name;
    const char *src;
    int want[4];
} wasm32_case_t;

#define WASM32_CASE_NARGS 4
